import { describe, expect, it } from "vitest";
import {
  type BackendResponseData,
  type ConversationEvent,
  type RawEvent,
  type UnionEventType,
  ConversationEventType,
  UtteranceType,
} from "../types";
import {
  extractSlotEventsForFlow,
  extractSlotEventsForSession,
  flowStepTrail,
  formatSlots,
  generateResponseData,
  getSlotRelatedEvents,
  isMemoryWriteEvent,
  isToolRunEvent,
  mapRawEventsToConversationEvents,
} from "./conversation";

function rawSkillEvent(event: RawEvent["event"], skillId: string, stepId?: string): RawEvent {
  return {
    event,
    skill_id: skillId,
    step_id: stepId,
    metadata: { active_flow: "ambient_flow" },
    timestamp: 1,
  } as RawEvent;
}

describe("mapRawEventsToConversationEvents skill lifecycle events", () => {
  it.each([
    ["skill_activated", ConversationEventType.SkillActivated],
    ["skill_completed", ConversationEventType.SkillCompleted],
    ["skill_cancelled", ConversationEventType.SkillCancelled],
    ["skill_interrupted", ConversationEventType.SkillInterrupted],
    ["skill_resumed", ConversationEventType.SkillResumed],
  ] as const)("maps %s with its skill id", (rawType, conversationType) => {
    const [event] = mapRawEventsToConversationEvents([rawSkillEvent(rawType, "card_replace")]);

    expect(event).toMatchObject({
      __typename: "ConversationEvent",
      conversationEventType: conversationType,
      skillId: "card_replace",
    });
    expect((event as ConversationEvent).flowId).toBeUndefined();
  });

  it("maps the step id for skill lifecycle events that carry one", () => {
    const [event] = mapRawEventsToConversationEvents([
      rawSkillEvent("skill_interrupted", "card_replace", "confirm_replacement"),
    ]);

    expect(event).toMatchObject({
      skillId: "card_replace",
      stepId: "confirm_replacement",
    });
  });

  it("maps the owning skill id on flow lifecycle events", () => {
    const [event] = mapRawEventsToConversationEvents([
      {
        ...rawSkillEvent("flow_started", "card_replace"),
        flow_id: "card_replace",
      },
    ]);

    expect(event).toMatchObject({
      conversationEventType: ConversationEventType.FlowStarted,
      flowId: "card_replace",
      skillId: "card_replace",
    });
  });

  it("keeps paired skill and flow lifecycle events as separate rows", () => {
    const events = mapRawEventsToConversationEvents([
      rawSkillEvent("skill_activated", "card_replace"),
      {
        ...rawSkillEvent("flow_started", "card_replace"),
        flow_id: "card_replace",
      },
    ]);

    expect(events).toHaveLength(2);
    expect(events.map((event) => (event as ConversationEvent).conversationEventType)).toEqual([
      ConversationEventType.SkillActivated,
      ConversationEventType.FlowStarted,
    ]);
  });
});

function rawOrderedBlockEvent(
  event: RawEvent["event"],
  skillId: string,
  blockId: string,
  stepId?: string,
): RawEvent {
  return {
    event,
    skill_id: skillId,
    block_id: blockId,
    step_id: stepId,
    metadata: { active_flow: "ambient_flow" },
    timestamp: 1,
  } as RawEvent;
}

describe("mapRawEventsToConversationEvents ordered-block lifecycle events", () => {
  it.each([
    ["ordered_block_entered", ConversationEventType.OrderedBlockEntered],
    ["ordered_block_completed", ConversationEventType.OrderedBlockCompleted],
    ["ordered_block_cancelled", ConversationEventType.OrderedBlockCancelled],
    ["ordered_block_interrupted", ConversationEventType.OrderedBlockInterrupted],
    ["ordered_block_resumed", ConversationEventType.OrderedBlockResumed],
  ] as const)("maps %s with skill and block ids", (rawType, conversationType) => {
    const [event] = mapRawEventsToConversationEvents([
      rawOrderedBlockEvent(rawType, "travel_notice", "submit"),
    ]);

    expect(event).toMatchObject({
      __typename: "ConversationEvent",
      conversationEventType: conversationType,
      skillId: "travel_notice",
      blockId: "submit",
    });
    expect((event as ConversationEvent).flowId).toBeUndefined();
  });

  it("maps the step id for ordered-block events that carry one", () => {
    const [event] = mapRawEventsToConversationEvents([
      rawOrderedBlockEvent("ordered_block_completed", "travel_notice", "submit", "confirm_dates"),
    ]);

    expect(event).toMatchObject({
      skillId: "travel_notice",
      blockId: "submit",
      stepId: "confirm_dates",
    });
  });

  it("keeps paired ordered-block and flow lifecycle events as separate rows", () => {
    const events = mapRawEventsToConversationEvents([
      {
        ...rawSkillEvent("flow_started", "travel_notice"),
        flow_id: "travel_notice__submit",
      },
      rawOrderedBlockEvent("ordered_block_entered", "travel_notice", "submit"),
    ]);

    expect(events).toHaveLength(2);
    expect(events.map((event) => (event as ConversationEvent).conversationEventType)).toEqual([
      ConversationEventType.FlowStarted,
      ConversationEventType.OrderedBlockEntered,
    ]);
    expect((events[0] as ConversationEvent).flowId).toBe("travel_notice__submit");
    expect((events[1] as ConversationEvent).blockId).toBe("submit");
  });
});

function rawToolEvent(
  event: "mcp_tool_executed" | "tool_executed",
  extra: Partial<RawEvent> = {},
): RawEvent {
  return {
    event,
    tool_name: "get_balance",
    arguments: { account: "1" },
    result: "ok",
    is_error: false,
    timestamp: 1,
    metadata: {},
    ...extra,
  } as RawEvent;
}

describe("mapRawEventsToConversationEvents tool run events", () => {
  it("maps tool_executed with source and mcp server", () => {
    const [event] = mapRawEventsToConversationEvents([
      rawToolEvent("tool_executed", { source: "mcp", mcp_server: "payments" }),
    ]);

    expect(event).toMatchObject({
      __typename: "ConversationEvent",
      conversationEventType: ConversationEventType.ToolExecuted,
      name: "get_balance",
    });
    expect((event as ConversationEvent).metadata).toMatchObject({
      tool_name: "get_balance",
      tool_arguments: { account: "1" },
      tool_result: "ok",
      tool_is_error: false,
      tool_source: "mcp",
      tool_mcp_server: "payments",
    });
  });

  it("maps a local tool_executed without a server", () => {
    const [event] = mapRawEventsToConversationEvents([
      rawToolEvent("tool_executed", { source: "local" }),
    ]);

    expect((event as ConversationEvent).conversationEventType).toBe(
      ConversationEventType.ToolExecuted,
    );
    expect((event as ConversationEvent).metadata.tool_source).toBe("local");
    expect((event as ConversationEvent).metadata.tool_mcp_server).toBeUndefined();
  });

  it("maps historical mcp_tool_executed as MCP with source mcp", () => {
    const [event] = mapRawEventsToConversationEvents([rawToolEvent("mcp_tool_executed")]);

    expect((event as ConversationEvent).conversationEventType).toBe(
      ConversationEventType.McpToolExecuted,
    );
    expect((event as ConversationEvent).metadata.tool_source).toBe("mcp");
    expect((event as ConversationEvent).metadata.tool_name).toBe("get_balance");
  });
});

function rawMemoryEvent(
  event: "memory_set" | "memory_cleared",
  extra: Partial<RawEvent> = {},
): RawEvent {
  return {
    event,
    key: "card_replace.replacement_reason",
    value: "stolen",
    timestamp: 1,
    metadata: {
      mantle_write_provenance: {
        tool: "check_replacement_eligibility",
        step: "confirm_reason",
      },
      parseData: {},
    },
    ...extra,
  } as RawEvent;
}

describe("mapRawEventsToConversationEvents memory events", () => {
  it("maps memory_set using the memory key and preserves provenance", () => {
    const [event] = mapRawEventsToConversationEvents([rawMemoryEvent("memory_set")]);

    expect(event).toMatchObject({
      __typename: "ConversationEvent",
      conversationEventType: ConversationEventType.MemorySet,
      name: "card_replace.replacement_reason",
      value: "stolen",
      metadata: {
        mantle_write_provenance: {
          tool: "check_replacement_eligibility",
          step: "confirm_reason",
        },
      },
    });
  });

  it("maps memory_cleared when the wire omits value", () => {
    const [event] = mapRawEventsToConversationEvents([
      {
        event: "memory_cleared",
        key: "travel_notice.note",
        timestamp: 1,
        metadata: {},
      } as unknown as RawEvent,
    ]);

    expect(event).toMatchObject({
      conversationEventType: ConversationEventType.MemoryCleared,
      name: "travel_notice.note",
      value: null,
    });
  });

  it("maps memory_set with a non-string value", () => {
    const [event] = mapRawEventsToConversationEvents([
      rawMemoryEvent("memory_set", {
        key: "travel_notice.notice_on",
        value: true,
      }),
    ]);

    expect(event).toMatchObject({
      conversationEventType: ConversationEventType.MemorySet,
      name: "travel_notice.notice_on",
      value: true,
    });
  });

  it.each([
    ConversationEventType.Slot,
    ConversationEventType.MemorySet,
    ConversationEventType.MemoryCleared,
  ])("recognizes %s as a memory write", (type) => {
    expect(
      isMemoryWriteEvent({
        ...slot("memory", "entry", "value"),
        conversationEventType: type,
      }),
    ).toBe(true);
  });
});

function slot(
  id: string,
  name: string,
  slotValue: null | string,
  timestamp = "100",
  metadata: Record<string, unknown> = {},
): ConversationEvent {
  return {
    id,
    conversationEventType: ConversationEventType.Slot,
    name,
    slotValue,
    timestamp,
    originalTimestamp: 0,
    metadata: { parseData: undefined, ...metadata },
    actionText: "",
    flowId: "",
    stepId: "",
    __typename: "ConversationEvent",
  };
}

