describe("mapRawEventsToConversationEvents", () => {
  it("maps barge-in playback context to a typed event", () => {
    const [event] = mapRawEventsToConversationEvents([
      {
        event: "user_barge_in",
        timestamp: 1,
        conversation_id: "conversation-1",
        metadata: {
          playback: {
            acknowledged_intermediate_markers: [{ kind: "audio_elapsed", offset_ms: 2000 }],
            total_audio_duration_ms: 8400,
          },
        },
      } as RawEvent,
    ]);

    expect(event).toMatchObject({
      conversationEventType: ConversationEventType.UserBargeIn,
      metadata: {
        playback: {
          acknowledged_intermediate_markers: [{ kind: "audio_elapsed", offset_ms: 2000 }],
          total_audio_duration_ms: 8400,
        },
      },
    });
  });

  it("maps silence timeouts to a typed event", () => {
    const [event] = mapRawEventsToConversationEvents([
      {
        event: "user_silence_timeout",
        timeout: 5,
        timestamp: 1,
      } as unknown as RawEvent,
    ]);

    expect(event).toMatchObject({
      conversationEventType: ConversationEventType.UserSilenceTimeout,
      timeout: 5,
      metadata: { rawEvent: { event: "user_silence_timeout", timeout: 5 } },
    });
  });

  it("maps suppressed input to a typed event", () => {
    const [event] = mapRawEventsToConversationEvents([
      {
        event: "user_input_suppressed",
        text: "hello",
        modality: "audio",
        reason: "below_min_words",
        timestamp: 1,
      } as unknown as RawEvent,
    ]);

    expect(event).toMatchObject({
      conversationEventType: ConversationEventType.UserInputSuppressed,
      text: "hello",
      modality: "audio",
      reason: "below_min_words",
      metadata: { rawEvent: { event: "user_input_suppressed" } },
    });
  });
});

describe("extractSlotEventsForFlow", () => {
  it("returns empty array if the flow never started", () => {
    const events: ConversationEvent[] = [
      slot("1", "some_slot", "test", "100"),
      flowCompleted("2", "some_other_flow", "200"),
    ];

    const result = extractSlotEventsForFlow(events, "target_flow");
    expect(result).toEqual([]);
  });

  it("returns slot events between FLOW_STARTED and FLOW_COMPLETED for the specified flow", () => {
    const memorySet = {
      ...slot("memory", "memory_entry", "stored", "102"),
      conversationEventType: ConversationEventType.MemorySet,
    };
    const events: ConversationEvent[] = [
      slot("1", "some_slot_outside", "should not be included", "100"),
      flowStarted("2", "target_flow", "101"),
      slot("3", "inside_slot_1", "123", "102"),
      memorySet,
      flowCompleted("4", "target_flow", "103"),
      slot("5", "some_slot_outside_2", "should not be included", "104"),
    ];

    const result = extractSlotEventsForFlow(events, "target_flow");
    expect(result.map((event) => event.id)).toEqual(["3", "memory"]);
  });

  it("returns slot events between FLOW_STARTED and FLOW_CANCELLED for the specified flow", () => {
    const events: ConversationEvent[] = [
      flowStarted("1", "target_flow", "200"),
      slot("2", "inside_slot_1", "first", "201"),
      slot("3", "inside_slot_2", "second", "202"),
      flowCancelled("4", "target_flow", "203"),
      slot("5", "outside_slot", "should not be included", "204"),
    ];

    const result = extractSlotEventsForFlow(events, "target_flow");
    expect(result).toHaveLength(2);
    expect(result.map((ev) => ev.id)).toEqual(["2", "3"]);
  });

  it("assumes the flow is ongoing if no FLOW_COMPLETED or FLOW_CANCELLED is found", () => {
    const events: ConversationEvent[] = [
      flowStarted("1", "target_flow", "300"),
      slot("2", "inside_slot_1", "ongoing 1", "301"),
      slot("3", "inside_slot_2", "ongoing 2", "302"),
    ];

    const result = extractSlotEventsForFlow(events, "target_flow");
    expect(result).toHaveLength(2);
    expect(result[0].slotValue).toBe("ongoing 1");
    expect(result[1].slotValue).toBe("ongoing 2");
  });

  it("extracts slots only for the given flow among nested flows", () => {
    const events: ConversationEvent[] = [
      // Flow A starts
      flowStarted("A1", "flowA", "400"),
      slot("A2", "slotA1", "belongs to flowA", "401"),

      // Flow B starts (stack is now [flowA, flowB])
      flowStarted("B1", "flowB", "402"),
      slot("B2", "slotB1", "belongs to flowB", "403"),

      // Flow B ends (stack reverts to [flowA])
      flowCompleted("B3", "flowB", "404"),

      // Slots now belong to the top (flowA) again
      slot("A3", "slotA2", "belongs to flowA again", "405"),

      // Flow A ends
      flowCancelled("A4", "flowA", "406"),
    ];

    const resultA = extractSlotEventsForFlow(events, "flowA");
    const resultB = extractSlotEventsForFlow(events, "flowB");

    // Flow A: slotA1, slotA2
    expect(resultA).toHaveLength(2);
    expect(resultA.map((x) => x.name)).toEqual(["slotA1", "slotA2"]);

    // Flow B: slotB1
    expect(resultB).toHaveLength(1);
    expect(resultB[0].name).toBe("slotB1");
  });
});

describe("extractSlotEventsForSession", () => {
  it("returns an empty array if no SESSION_STARTED event is found", () => {
    const events: ConversationEvent[] = [
      slot("1", "slotX", "test", "100"),
      flowStarted("2", "some_flow", "101", { flow_id: "some_flow" }),
    ];

    const result = extractSlotEventsForSession(events);
    expect(result).toEqual([]);
  });

  it("returns all slot events from the first SESSION_STARTED to the end", () => {
    const events: ConversationEvent[] = [
      slot("1", "slotX", "test", "90"),
      sessionStarted("2", "100"),
      flowStarted("3", "some_flow", "110", { flow_id: "some_flow" }),
      slot("4", "slotY", "123", "120"),
      {
        ...slot("5", "memory_entry", "stored", "130"),
        conversationEventType: ConversationEventType.MemorySet,
      },
    ];

    const result = extractSlotEventsForSession(events);
    expect(result.map((e) => e.id)).toEqual(["4", "5"]);
  });

  it("works if SESSION_STARTED is at the very beginning", () => {
    const events: ConversationEvent[] = [
      sessionStarted("1", "1"),
      slot("2", "slot_after_start", "hello", "2"),
    ];

    const result = extractSlotEventsForSession(events);
    expect(result.length).toBe(1);
    expect(result[0].id).toBe("2");
  });
});

describe("formatSlots", () => {
  it("returns an empty array if no slot events exist", () => {
    const result = formatSlots([]);
    expect(result).toEqual([]);
  });

  it("maps each slot event to { name, value } pairs", () => {
    const slotEvents = [slot("1", "slotA", "valueA", "10"), slot("2", "slotB", "42", "11")];
    const result = formatSlots(slotEvents);
    expect(result).toEqual(
      expect.arrayContaining([
        expect.objectContaining({ name: "slotA", value: "valueA" }),
        expect.objectContaining({ name: "slotB", value: "42" }),
      ]),
    );
  });

  it("overwrites previous slot values if the same slot name is repeated", () => {
    const slotEvents = [
      slot("1", "slotA", "100", "1"),
      slot("2", "slotB", "200", "2"),
      slot("3", "slotA", "999", "3"), // redefines slotA
    ];
    // final: slotA=999, slotB=200
    const result = formatSlots(slotEvents);
    expect(result).toEqual(
      expect.arrayContaining([
        expect.objectContaining({ name: "slotA", value: "999" }),
        expect.objectContaining({ name: "slotB", value: "200" }),
      ]),
    );
  });
});

describe("getSlotRelatedEvents", () => {
  it("returns only conversation events that are slot-related or allowed flow/session events", () => {
    const events: UnionEventType[] = [
      slot("slot1", "slotName", "slotVal", "100"),
      {
        ...slot("memory1", "memoryName", "memoryVal", "105"),
        conversationEventType: ConversationEventType.MemorySet,
      },
      flowStarted("flowStartA", "some_flow", "110"),
      flowStarted("flowStartPattern", "pattern_error_handling", "120"),
      flowCancelled("flowCancelPattern", "pattern_whatever", "130"),
      flowCancelled("flowCancelRegular", "some_flow", "140"),
      sessionStarted("sessionStarted", "150"),
      flowCompleted("flowCompleteRegular", "some_flow", "160"),
    ];

    const relatedEvents = getSlotRelatedEvents(events);

    // Expect to exclude any flow.* with "pattern_" in the flowId
    expect(relatedEvents.map((e) => e.id)).toEqual([
      "slot1",
      "memory1",
      "flowStartA",
      "flowCancelRegular",
      "sessionStarted",
      "flowCompleteRegular",
    ]);
  });

  it("filters out pattern_* flows on started, completed, or cancelled", () => {
    const events: UnionEventType[] = [
      flowStarted("pstart1", "pattern_cancel_flow", "100"),
      flowCompleted("pcomplete1", "pattern_handle_error", "100"),
      flowCancelled("pcancel1", "pattern_something", "100"),
      flowStarted("regularFlowStart", "non_pattern_flow", "100"),
      slot("slot1", "regularSlot", "val", "100"),
    ];

    const relatedEvents = getSlotRelatedEvents(events);

    // Only "regularFlowStart" and slot "slot1" remain
    expect(relatedEvents.map((e) => e.id)).toEqual(["regularFlowStart", "slot1"]);
  });
});

describe("generateResponseData", () => {
  it("extracts attachment URL from markdown link in text", () => {
    const result = generateResponseData({
      text: "See [report](https://example.com/report.pdf)",
    } as BackendResponseData);

    expect(result.attachment).toBe("https://example.com/report.pdf");
    expect(result.buttons).toEqual([]);
    expect(result.quickReplies).toEqual([]);
  });

  it("allows whitespace between label and url parentheses", () => {
    const result = generateResponseData({
      text: "Get [doc]  (https://x.com/a)",
    } as BackendResponseData);

    expect(result.attachment).toBe("https://x.com/a");
  });

  it("does not set attachment when text has no markdown link", () => {
    const result = generateResponseData({
      text: "plain message",
    } as BackendResponseData);

    expect(result.attachment).toBeUndefined();
  });

  it("prefers explicit link attachment over markdown in text", () => {
    const result = generateResponseData({
      text: "[x](from-text)",
      attachment: {
        type: "link",
        payload: { url: "from-object", src: "", elements: "" },
      },
    } as BackendResponseData);

    expect(result.attachment).toBe("from-object");
  });
});

function toolRunEvent(
  id: string,
  toolName: string,
  type: ConversationEventType.McpToolExecuted | ConversationEventType.ToolExecuted,
): ConversationEvent {
  return {
    id,
    conversationEventType: type,
    name: toolName,
    slotValue: null,
    timestamp: "100",
    originalTimestamp: 0,
    metadata: { parseData: undefined, tool_name: toolName },
    actionText: "",
    flowId: "",
    stepId: "",
    __typename: "ConversationEvent",
  };
}

const toolRunTypes = [
  ConversationEventType.McpToolExecuted,
  ConversationEventType.ToolExecuted,
] as const;

describe("isToolRunEvent", () => {
  it.each(toolRunTypes)("is true for %s", (type) => {
    expect(isToolRunEvent(toolRunEvent("m", "get_balance", type))).toBe(true);
  });

  it("is false for slots, llm calls, and utterances", () => {
    expect(isToolRunEvent(slot("s", "amount", "value"))).toBe(false);
    expect(
      isToolRunEvent({
        id: "l",
        conversationEventType: ConversationEventType.LlmCallRecorded,
        name: "",
        slotValue: null,
        timestamp: "100",
        originalTimestamp: 0,
        metadata: { parseData: undefined },
        actionText: "",
        flowId: "",
        stepId: "",
        __typename: "ConversationEvent",
      }),
    ).toBe(false);
    expect(
      isToolRunEvent({
        __typename: "Utterance",
        id: "u",
        metadata: { parseData: undefined },
        rephrase: false,
        rephrasePrompt: null,
        text: "hi",
        timestamp: "100",
        originalTimestamp: 0,
        tokens: [],
        type: UtteranceType.User,
      }),
    ).toBe(false);
  });
});

describe("mapRawEventsToConversationEvents deterministic ids", () => {
  function rawEvent(event: RawEvent["event"], timestamp: number): RawEvent {
    return { event, timestamp } as RawEvent;
  }

  const rawList: RawEvent[] = [rawEvent("user", 100), rawEvent("bot", 101), rawEvent("slot", 102)];

  it("assigns identical ids when the same raw list is mapped twice", () => {
    const first = mapRawEventsToConversationEvents(rawList).map((event) => event.id);
    const second = mapRawEventsToConversationEvents(rawList).map((event) => event.id);
    expect(second).toEqual(first);
  });

  it("keeps existing ids stable when a new event is appended", () => {
    const before = mapRawEventsToConversationEvents(rawList).map((event) => event.id);
    const after = mapRawEventsToConversationEvents([...rawList, rawEvent("bot", 103)]).map(
      (event) => event.id,
    );
    expect(after.slice(0, before.length)).toEqual(before);
    expect(after).toHaveLength(before.length + 1);
  });

  it("derives the id from position, event type, and timestamp", () => {
    const [user, bot, slotEvent] = mapRawEventsToConversationEvents(rawList);
    expect(user.id).toBe("event-0-user-100");
    expect(bot.id).toBe("event-1-bot-101");
    expect(slotEvent.id).toBe("event-2-slot-102");
  });
});

describe("flowStepTrail", () => {
  function stackEvent(update: unknown, id: string): UnionEventType {
    return {
      __typename: "StackEvent",
      id,
      metadata: {},
      timestamp: "1",
      update: JSON.stringify(update),
    } as unknown as UnionEventType;
  }

  it("accumulates every step the flow passed through from stack updates", () => {
    // The dialogue stack carries the active step on each update, so transient
    // steps (an execute/set step between the entry and the resting step) show
    // up even though they emit no step-stamped event of their own.
    const events: UnionEventType[] = [
      stackEvent(
        [
          {
            op: "add",
            path: "/0",
            value: { flow_id: "card_disambiguation__main", step_id: "START" },
          },
        ],
        "s0",
      ),
      stackEvent([{ op: "replace", path: "/0/step_id", value: "clear_selected_card" }], "s1"),
      stackEvent([{ op: "replace", path: "/0/step_id", value: "collect_card" }], "s2"),
    ];
    expect(flowStepTrail(events)).toEqual({
      card_disambiguation__main: ["START", "clear_selected_card", "collect_card"],
    });
  });

  it("collapses repeated identical steps but keeps distinct transitions", () => {
    const events: UnionEventType[] = [
      stackEvent([{ op: "add", path: "/0", value: { flow_id: "f", step_id: "START" } }], "s0"),
      stackEvent([{ op: "replace", path: "/0/step_id", value: "a" }], "s1"),
      stackEvent([{ op: "replace", path: "/0/step_id", value: "a" }], "s2"),
      stackEvent([{ op: "replace", path: "/0/step_id", value: "b" }], "s3"),
    ];
    // Consecutive identical steps are recorded once per update (loops allowed);
    // the trail preserves order for edge highlighting.
    expect(flowStepTrail(events).f).toEqual(["START", "a", "a", "b"]);
  });
});
